    # Owner mismatch must be detected before any store access or compute call.
    if task['owner'] != profile['owner']:
        raise PermissionError('owner mismatch')

    # Version mismatch returns None with no side effects.
    if task['version'] != profile['version']:
        return None

    # Cache key spans owner, profile.version, criteria_version, and job_text.
    # Components may legitimately be 0/None and must be preserved as-is.
    key = (task['owner'], profile['version'], task['criteria_version'], task['job_text'])

    # Reuse only when the key is already present; a None result is a valid
    # cached value and must also be reused.
    if key in store:
        return store[key]

    result = compute()  # exceptions propagate and are never cached
    store[key] = result
    return result
