        'version': version,
        'job_text': job_text,
        'criteria_version': criteria_version,
    }


def base_profile(owner, version):
    return {'owner': owner, 'version': version}


def test_owner_match_computes_and_caches():
    store = {}
    task = base_task('alice', 1, 'job-x', 'c1')
    profile = base_profile('alice', 1)

    calls = []

    def compute():
        calls.append(1)
        return 'result-x'

    assert evaluate(store, task, profile, compute) == 'result-x'
    assert store == {('alice', 1, 'c1', 'job-x'): 'result-x'}
    assert len(calls) == 1

    # unchanged input reuses cache
    assert evaluate(store, task, profile, compute) == 'result-x'
    assert len(calls) == 1


def test_owner_mismatch_raises_before_store_compute():
    store = {'poison': 'store-write'}
    task = base_task('mallory', 1, 'job-x', 'c1')
    profile = base_profile('alice', 1)
    calls = []

    try:
        evaluate(store, task, profile, compute=lambda: calls.append(1) or 'boom')
        assert False, 'expected PermissionError'
    except PermissionError:
        pass

    assert 'poison' not in store
    assert calls == []


def test_version_mismatch_returns_none_without_side_effects():
    store = {}
    task = base_task('alice', 5, 'job-x', 'c1')
    profile = base_profile('alice', 1)
    calls = []

    assert evaluate(store, task, profile, compute=lambda: calls.append(1) or 'boom') is None
    assert store == {}
    assert calls == []


def test_zero_none_inputs_still_cached():
    store = {}
    task = base_task('bob', 0, None, criteria_version=None)
    profile = base_profile('bob', 0)

    calls = []
    def compute():
        calls.append(1)
        return None

    assert evaluate(store, task, profile, compute) is None
    assert store == {('bob', 0, None, None): None}
    assert len(calls) == 1

    assert evaluate(store, task, profile, compute) is None
    assert len(calls) == 1


def test_exceptions_propagate_and_not_cached():
